def choose_move(observation):
    width=observation["grid_width"]
    height=observation["grid_height"]
    pos=observation["self_position"]
    ox,oy=observation["opponent_position"]
    resources=observation["resources"]
    obstacles=observation["obstacles"]
    scores=observation["scores"]
    # Helper grid checks
    def free(x,y): return 0<=x<width and 0<=y<height and [x,y] not in obstacles
    # Find closest resource
    res_pos=None
    min_dist=float('inf')
    for r in resources:
        rx,ry=r
        dist=abs(rx-pos[0])+abs(ry-pos[1])
        if dist<min_dist:
            min_dist=dist
            res_pos=(rx,ry)
    # Move towards a target if exists
    def move_towards(target):
        dx=dy=0
        if target[0]>pos[0] and free(pos[0]+1,pos[1]):
            dx=1
        elif target[0]<pos[0] and free(pos[0]-1,pos[1]):
            dx=-1
        elif target[1]>pos[1] and free(pos[0],pos[1]+1):
            dy=1
        elif target[1]<pos[1] and free(pos[0],pos[1]-1):
            dy=-1
        # fallback to random safe move
        if dx==dy==0:
            if free(pos[0]+1,pos[1]):dx=1
            elif free(pos[0]-1,pos[1]):dx=-1
            elif free(pos[0],pos[1]+1]):dy=1
            elif free(pos[0],pos[1]-1):dy=-1
        return [dx,dy]
    # Chase opponent if closer than resource or no resource
    dist_op=abs(ox - pos[0])+abs(oy - pos[1])
    if res_pos and dist_op>min_dist:
        return move_towards(res_pos)
    else:
        return move_towards((ox,oy))
